*{box-sizing:border-box}body{margin:0;background:#f5f7fb;color:#111827;font-family:Inter,Arial,sans-serif}.top{height:70px;background:#fff;border-bottom:1px solid #e5e7eb;display:flex;align-items:center;justify-content:space-between;padding:0 6%;position:sticky;top:0;z-index:10}.brand{font-weight:800}.actions{display:flex;align-items:center;gap:10px}.btn{border:0;border-radius:10px;padding:10px 14px;font-size:12px;font-weight:800;cursor:pointer;text-decoration:none}.btn-primary{background:#4f46e5;color:#fff}.btn-danger{background:#fee2e2;color:#b91c1c}.btn-light{background:#f3f4f6;color:#374151}.wrap{max-width:1000px;margin:auto;padding:42px 24px 70px}.hello{color:#4f46e5;font-size:11px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.wrap h1{font-size:32px;margin:8px 0}.sub{color:#6b7280;font-size:13px}.grid{display:grid;grid-template-columns:1.2fr .8fr;gap:18px;margin-top:28px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:18px;padding:24px;box-shadow:0 10px 30px #0f172a08}.card h2{font-size:17px;margin:0 0 17px}.row{display:flex;justify-content:space-between;gap:20px;padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:12px}.row:last-child{border:0}.label{color:#6b7280}.value{font-weight:700;text-align:right;word-break:break-word}.role{display:inline-block;background:#eef2ff;color:#4338ca;border-radius:8px;padding:6px 9px;font-size:10px;font-weight:800}.notice{font-size:11px;line-height:1.6;color:#6b7280;margin-top:15px}.modal{position:fixed;inset:0;background:#11182780;display:none;place-items:center;padding:20px;z-index:30}.modal.show{display:grid}.modal-box{width:min(540px,100%);background:#fff;border-radius:20px;padding:25px;box-shadow:0 25px 80px #0003}.modal-head{display:flex;justify-content:space-between;align-items:start;gap:15px}.modal-head h2{margin:0;font-size:20px}.close{border:0;background:#f3f4f6;border-radius:9px;width:34px;height:34px;cursor:pointer}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:18px}.field.full{grid-column:1/-1}.field label{display:block;font-size:11px;font-weight:800;margin-bottom:7px;color:#374151}.control{width:100%;height:42px;border:1px solid #d1d5db;border-radius:10px;padding:0 12px;font-size:12px;outline:0}.control:focus{border-color:#818cf8;box-shadow:0 0 0 4px #6366f11a}.helper{font-size:10px;color:#9ca3af;margin-top:6px;line-height:1.4}.modal-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:20px}.alert{display:none;padding:10px 12px;border-radius:10px;font-size:11px;margin-top:14px}.alert.show{display:block}.alert.error{background:#fef2f2;color:#b91c1c}.alert.success{background:#ecfdf5;color:#047857}.spinner{width:13px;height:13px;border:2px solid #ffffff66;border-top-color:#fff;border-radius:50%;display:inline-block;animation:spin .7s linear infinite;vertical-align:-2px}@keyframes spin{to{transform:rotate(360deg)}}
