<header class="top"><div class="brand">Ujian ASTS</div><div class="actions"><button class="btn btn-light" onclick="openEdit()">Edit Akun</button><button class="btn btn-danger" onclick="openDelete()">Hapus Akun</button><a class="btn btn-light" href="logout.php">Keluar</a></div></header>
<main class="wrap"><div class="hello">User Dashboard</div><h1>Halo, <?= htmlspecialchars($user['name'], ENT_QUOTES, 'UTF-8') ?>.</h1><p class="sub">Kelola data akunmu sendiri. Perubahan penting akan diberitahukan melalui WhatsApp.</p>
<div class="grid"><section class="card"><h2>Profil Akun</h2><div class="row"><span class="label">Nama</span><span class="value" id="viewName"><?= htmlspecialchars($user['name'], ENT_QUOTES, 'UTF-8') ?></span></div><div class="row"><span class="label">Email</span><span class="value" id="viewEmail"><?= htmlspecialchars($user['email'], ENT_QUOTES, 'UTF-8') ?></span></div><div class="row"><span class="label">WhatsApp</span><span class="value" id="viewWhatsapp"><?= htmlspecialchars($user['whatsapp'], ENT_QUOTES, 'UTF-8') ?></span></div><div class="row"><span class="label">Role</span><span class="value"><span class="role">USER</span></span></div><p class="notice">Saat akun diperbarui, sistem mengirim notifikasi ke nomor WhatsApp akun. Saat akun dihapus, notifikasi dikirim sebelum sesi akun ditutup.</p></section><section class="card"><h2>Akses</h2><div style="width:48px;height:48px;border-radius:14px;background:#eef2ff;color:#4f46e5;display:grid;place-items:center;font-weight:800;margin-bottom:15px"><?= htmlspecialchars($initials ?: 'U') ?></div><span class="role">USER ACCOUNT</span><p class="notice">Akun user tidak dapat membuka dashboard admin atau mengubah role sendiri.</p></section></div></main>

<div class="modal" id="editModal"><div class="modal-box"><div class="modal-head"><div><h2>Edit Akun</h2><div class="helper">Masukkan password saat ini jika ingin mengganti password.</div></div><button class="close" onclick="closeModal('editModal')">×</button></div><div id="editAlert" class="alert"></div><form id="editForm"><div class="form-grid"><div class="field full"><label>Nama lengkap</label><input class="control" name="name" id="editName" required maxlength="100"></div><div class="field"><label>Email</label><input class="control" name="email" id="editEmail" type="email" required maxlength="150"></div><div class="field"><label>WhatsApp</label><input class="control" name="whatsapp" id="editWhatsapp" required inputmode="numeric" maxlength="15"><div class="helper">Jika nomor diubah, pastikan nomor baru aktif.</div></div><div class="field"><label>Password baru (opsional)</label><input class="control" name="password" type="password" minlength="6" placeholder="Kosongkan jika tidak diubah"></div><div class="field"><label>Password saat ini</label><input class="control" name="current_password" type="password" required></div></div><div class="modal-actions"><button type="button" class="btn btn-light" onclick="closeModal('editModal')">Batal</button><button class="btn btn-primary" id="saveBtn">Simpan Perubahan</button></div></form></div></div>
<div class="modal" id="deleteModal"><div class="modal-box"><div class="modal-head"><div><h2>Hapus Akun?</h2><div class="helper">Tindakan ini permanen dan akun tidak bisa dipulihkan dari halaman ini.</div></div><button class="close" onclick="closeModal('deleteModal')">×</button></div><div id="deleteAlert" class="alert"></div><form id="deleteForm"><div class="field" style="margin-top:18px"><label>Password saat ini</label><input class="control" name="password" type="password" required></div><div class="modal-actions"><button type="button" class="btn btn-light" onclick="closeModal('deleteModal')">Batal</button><button class="btn btn-danger" id="deleteBtn">Hapus Akun Permanen</button></div></form></div></div>
<script>
const account={name:<?=json_encode($user['name'])?>,email:<?=json_encode($user['email'])?>,whatsapp:<?=json_encode($user['whatsapp'])?>};
function openEdit(){document.getElementById('editName').value=account.name;document.getElementById('editEmail').value=account.email;document.getElementById('editWhatsapp').value=account.whatsapp;document.getElementById('editForm').querySelector('[name=password]').value='';document.getElementById('editForm').querySelector('[name=current_password]').value='';document.getElementById('editModal').classList.add('show');}
function openDelete(){document.getElementById('deleteForm').reset();document.getElementById('deleteModal').classList.add('show');}
function closeModal(id){document.getElementById(id).classList.remove('show');}
function alertBox(id,msg,type){const e=document.getElementById(id);e.className='alert show '+type;e.textContent=msg;}
async function post(form){const res=await fetch('account_actions.php',{method:'POST',body:form});const text=await res.text();let json;try{json=JSON.parse(text)}catch(e){throw new Error('Server mengembalikan respons tidak valid.')}if(!json.success)throw new Error(json.message||'Proses gagal.');return json;}
document.getElementById('editForm').addEventListener('submit',async e=>{e.preventDefault();const b=document.getElementById('saveBtn');b.disabled=true;b.innerHTML='<span class="spinner"></span> Menyimpan';try{const fd=new FormData(e.target);fd.set('action','self_update');const d=await post(fd);account.name=d.account.name;account.email=d.account.email;account.whatsapp=d.account.whatsapp;document.getElementById('viewName').textContent=account.name;document.getElementById('viewEmail').textContent=account.email;document.getElementById('viewWhatsapp').textContent=account.whatsapp;alertBox('editAlert','Data berhasil diperbarui.'+(d.notification?.sent?' Notifikasi WhatsApp terkirim.':''),'success');setTimeout(()=>location.reload(),900);}catch(err){alertBox('editAlert',err.message,'error')}finally{b.disabled=false;b.textContent='Simpan Perubahan';}});
document.getElementById('deleteForm').addEventListener('submit',async e=>{e.preventDefault();if(!confirm('Yakin ingin menghapus akun secara permanen?'))return;const b=document.getElementById('deleteBtn');b.disabled=true;b.textContent='Menghapus...';try{const fd=new FormData(e.target);fd.set('action','self_delete');const d=await post(fd);alertBox('deleteAlert','Akun dihapus.'+(d.notification?.sent?' Notifikasi WhatsApp terkirim.':''),'success');setTimeout(()=>location.href='login.php',1200);}catch(err){alertBox('deleteAlert',err.message,'error');b.disabled=false;b.textContent='Hapus Akun Permanen';}});
</script></body></html>
